// ============================================================================
//  short-lesson-plan-template.js
//  ---------------------------------------------------------------------------
//  AUTO-GENERATED wrapper that exports the Short Lesson Plan HTML template as
//  a JavaScript string constant.  We inline the file this way so that
//  Next.js `output: 'standalone'` bundles the asset via webpack tracing —
//  filesystem reads of .html assets outside `public/` do NOT survive
//  standalone builds and cause GET /api/short-lesson-plans/template to
//  return HTTP 500 in production.
//
//  ⚠️  DO NOT edit this file by hand — regenerate it from
//     `short-lesson-plan-template.html` whenever the template changes.
// ============================================================================

export const SHORT_LESSON_PLAN_TEMPLATE_HTML = "<!DOCTYPE html>\n<html lang=\"or\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Short Lesson Plan · LessonGuru Odisha</title>\n\n<!--\n  ══════════════════════════════════════════════════════════════════════════\n  LESSONGURU ODISHA — SHORT LESSON PLAN TEMPLATE (v2 · card style)\n  ─────────────────────────────────────────────────────────────────────────\n  The <meta name=\"em-*\"> block below is REQUIRED.  The Short Lesson Plans\n  ingest pipeline reads these tags to auto-populate the DB — do NOT rename\n  them.  Everything visible on screen comes from the <body> HTML below;\n  replace the placeholder Odia text with your actual lesson content.\n\n  em-class          → Class name in English (Class 1 … Class 10 / Balvatika)\n  em-book           → Book / textbook name\n  em-subject        → Subject in Odia (e.g. ଓଡ଼ିଆ ଭାଷା, ପରିବେଶ ଅଧ୍ୟୟନ)\n  em-chapter        → Chapter title in Odia\n  em-chapter-order  → 0-based chapter index (0, 1, 2 …)\n  em-period         → Period number within the chapter (1, 2, 3 …)\n  em-day            → Global teaching day (1..190) — UNIQUE per subject/year\n  em-lo             → Learning Outcome code (e.g. LLD-9.3.2)\n  em-dakhyata       → Dakhyata (competency) code (e.g. LLD-9.3)\n  em-cg             → Curricular Goal code (e.g. CG-9)\n  ══════════════════════════════════════════════════════════════════════════\n-->\n<meta name=\"em-class\"          content=\"Class 1\">\n<meta name=\"em-book\"           content=\"ଝୁଲଣା-୧ (Jhulana-1)\">\n<meta name=\"em-subject\"        content=\"ଓଡ଼ିଆ ଭାଷା\">\n<meta name=\"em-chapter\"        content=\"ବିଦ୍ୟାଳୟ ପ୍ରସ୍ତୁତି କାର୍ଯ୍ୟକ୍ରମ\">\n<meta name=\"em-chapter-order\"  content=\"0\">\n<meta name=\"em-period\"         content=\"1\">\n<meta name=\"em-day\"            content=\"1\">\n<meta name=\"em-lo\"             content=\"LLD-9.3.2\">\n<meta name=\"em-dakhyata\"       content=\"LLD-9.3\">\n<meta name=\"em-cg\"             content=\"CG-9\">\n\n<style>\n  @import url('https://fonts.googleapis.com/css2?family=Noto+Sans+Oriya:wght@400;500;600;700;800&family=Inter:wght@400;600;700;800&display=swap');\n  *, *::before, *::after { box-sizing: border-box; }\n  html, body { margin: 0; padding: 0; }\n  body {\n    font-family: 'Noto Sans Oriya', 'Nirmala UI', 'Kalinga', 'Lohit Odia', 'Inter', system-ui, sans-serif;\n    color: #0f172a;\n    background: #f5f7fb;\n    padding: 12px;\n    line-height: 1.55;\n    -webkit-font-smoothing: antialiased;\n    position: relative;\n  }\n  /* ── Diagonal \"Premium\" watermark repeated across the page ─────────── */\n  body::before {\n    content: '';\n    position: fixed;\n    inset: 0;\n    background-image: repeating-linear-gradient(-24deg,\n        transparent 0 220px,\n        rgba(99, 102, 241, 0.055) 220px 245px);\n    pointer-events: none;\n    z-index: 0;\n  }\n  body::after {\n    content: 'LessonGuruOdisha Premium · Personal Use Only';\n    position: fixed;\n    inset: 0;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    color: rgba(15, 23, 42, 0.045);\n    font-size: 42pt;\n    font-weight: 900;\n    transform: rotate(-30deg);\n    letter-spacing: 2px;\n    pointer-events: none;\n    z-index: 0;\n  }\n  .sheet {\n    position: relative;\n    z-index: 1;\n    max-width: 860px;\n    margin: 0 auto;\n    background: #ffffff;\n    border-radius: 18px;\n    padding: 18px 18px 24px;\n    box-shadow: 0 10px 40px -20px rgba(15, 23, 42, 0.25),\n                0 3px 12px -8px rgba(15, 23, 42, 0.15);\n  }\n  h1, h2, h3, h4 { margin: 0; line-height: 1.35; font-weight: 800; }\n  p { margin: 0; }\n\n  /* Topic banner */\n  .topic-banner {\n    background: linear-gradient(135deg, #fee2e2 0%, #fef3c7 100%);\n    border: 1px solid #fecaca;\n    border-radius: 12px;\n    padding: 14px 16px;\n    margin-bottom: 14px;\n  }\n  .topic-banner .label {\n    font-size: 10.5pt; font-weight: 900; color: #b91c1c;\n    letter-spacing: 0.4px; text-transform: uppercase;\n  }\n  .topic-banner .topic {\n    font-size: 12.5pt; color: #0f172a; font-weight: 700;\n    margin-top: 4px; line-height: 1.5;\n  }\n  .topic-banner .icon { font-size: 15pt; margin-right: 4px; }\n\n  /* Section heading */\n  .section-title {\n    font-size: 13pt; color: #b91c1c; font-weight: 900;\n    margin: 18px 0 10px; letter-spacing: 0.3px;\n  }\n  .section-title .em { font-size: 14pt; }\n\n  /* Panchapadi cards */\n  .step { border-radius: 14px; margin-bottom: 12px; overflow: hidden;\n          border: 1px solid rgba(15, 23, 42, 0.06); }\n  .step .step-header {\n    color: #fff; padding: 10px 14px;\n    display: flex; align-items: center; gap: 8px;\n    font-weight: 800; font-size: 11.5pt;\n  }\n  .step .step-header .duration {\n    margin-left: auto;\n    background: rgba(255, 255, 255, 0.25);\n    border-radius: 999px;\n    padding: 3px 10px; font-size: 9.5pt;\n    font-weight: 800; white-space: nowrap;\n  }\n  .step .step-body { background: #ffffff; padding: 12px 14px 14px; }\n  .step .role {\n    font-size: 9.5pt; font-weight: 900; letter-spacing: 0.4px;\n    text-transform: uppercase; margin: 8px 0 4px;\n  }\n  .step .role.teacher { color: #2563eb; }\n  .step .role.example { color: #059669; }\n  .step .role .em { margin-right: 3px; }\n  .step .body-text { font-size: 10.5pt; color: #1e293b; line-height: 1.7; }\n\n  .step.adhiti  .step-header { background: linear-gradient(135deg, #3b82f6, #4338ca); }\n  .step.bodha   .step-header { background: linear-gradient(135deg, #10b981, #0d9488); }\n  .step.abhyasa .step-header { background: linear-gradient(135deg, #f97316, #ea580c); }\n  .step.prayoga .step-header { background: linear-gradient(135deg, #a855f7, #6d28d9); }\n  .step.prasara .step-header { background: linear-gradient(135deg, #ef4444, #b91c1c); }\n\n  /* Visual cue (yellow) */\n  .visual-cue {\n    background: linear-gradient(90deg, #fefce8 0%, #fef9c3 100%);\n    border: 1px solid #fde68a;\n    border-radius: 10px;\n    padding: 10px 14px; margin: 14px 0;\n    font-size: 10.5pt; line-height: 1.6;\n  }\n  .visual-cue .label { font-weight: 900; color: #b45309; margin-right: 6px; }\n\n  /* Grid */\n  .grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }\n  @media (max-width: 640px) { .grid-2 { grid-template-columns: 1fr; } }\n  .info-card {\n    background: #faf5ff; border: 1px solid #ede9fe;\n    border-radius: 10px; padding: 10px 14px;\n    font-size: 10pt; line-height: 1.7;\n  }\n  .info-card .h {\n    font-weight: 900; color: #7c3aed;\n    font-size: 10pt; letter-spacing: 0.3px; margin-bottom: 4px;\n  }\n  .info-card ol, .info-card ul { margin: 4px 0 0; padding-left: 18px; }\n  .info-card.hots     .h { color: #db2777; }\n  .info-card.activity .h { color: #0284c7; }\n  .info-card.write    .h { color: #059669; }\n\n  /* Inclusive education */\n  .inclusive {\n    background: #fff1f2; border-left: 4px solid #e11d48;\n    border-radius: 6px; padding: 10px 14px;\n    margin: 14px 0; font-size: 10pt;\n  }\n  .inclusive .h { font-weight: 900; color: #be123c; margin-bottom: 4px; }\n  .inclusive ul { margin: 4px 0 0; padding-left: 20px; }\n  .inclusive li { margin: 3px 0; }\n  .inclusive li b { color: #0f172a; }\n\n  /* Tri-column footer */\n  .tri-col {\n    display: grid; grid-template-columns: repeat(3, 1fr);\n    gap: 10px; margin-top: 14px; padding-top: 14px;\n    border-top: 1px dashed #cbd5e1;\n  }\n  @media (max-width: 640px) { .tri-col { grid-template-columns: 1fr; } }\n  .tri-col .cell { font-size: 9.5pt; line-height: 1.5; }\n  .tri-col .cell .h {\n    font-weight: 900; font-size: 9.5pt;\n    letter-spacing: 0.4px; text-transform: uppercase;\n    margin-bottom: 4px; color: #7c3aed;\n  }\n  .tri-col .cell.century .h { color: #0284c7; }\n  .tri-col .cell.nep     .h { color: #059669; }\n\n  /* Nav row */\n  .nav-row {\n    display: flex; gap: 8px; margin-top: 18px; align-items: center;\n    justify-content: space-between;\n  }\n  .nav-row button {\n    font-family: inherit; font-size: 10pt; font-weight: 800;\n    padding: 8px 16px; border-radius: 8px;\n    background: linear-gradient(135deg, #4f46e5, #7c3aed);\n    color: #fff; border: 0; cursor: pointer;\n  }\n  .nav-row button.secondary {\n    background: #ffffff; color: #4f46e5;\n    border: 1px solid #c7d2fe;\n  }\n\n  @media print {\n    body { background: #fff; padding: 0; }\n    body::before, body::after { display: none; }\n    .sheet { box-shadow: none; border-radius: 0; margin: 0; padding: 6mm 5mm; }\n    .step, .info-card, .visual-cue, .inclusive, .topic-banner { break-inside: avoid; }\n    .nav-row, .no-print { display: none !important; }\n    @page { size: A4 portrait; margin: 7mm; }\n    * { -webkit-print-color-adjust: exact; print-color-adjust: exact; }\n  }\n</style>\n</head>\n<body>\n<article class=\"sheet\">\n\n  <!-- ═════ Topic banner ═════ -->\n  <div class=\"topic-banner\">\n    <div class=\"label\"><span class=\"icon\">📘</span>ବିଷୟବସ୍ତୁ / TOPIC</div>\n    <div class=\"topic\">ଆଜି ଚିତ୍ର ଦେଖି କଥା ଦେବା।</div>\n  </div>\n\n  <!-- ═════ Panchapadi Sopana — 5 teaching steps ═════ -->\n  <h2 class=\"section-title\"><span class=\"em\">🎯</span> ପଞ୍ଚପଦୀ ସୋପାନ / PANCHAPADI STEPS</h2>\n\n  <div class=\"step adhiti\">\n    <div class=\"step-header\">\n      <span>୧</span>\n      <span>ଅଧୀତି (Adhiti) — Introduction / Preparation</span>\n      <span class=\"duration\">5 Min</span>\n    </div>\n    <div class=\"step-body\">\n      <div class=\"role teacher\"><span class=\"em\">📘</span> ଶିକ୍ଷକ କାର୍ଯ୍ୟ (TEACHER)</div>\n      <div class=\"body-text\">\"ପିଲାମାନେ, ଆଜି ଦେଖନ୍ତୁ ପୁସ୍ତକର ଡାହାଣ ଦେଇ ମୋ ଚିତ୍ର ବିଡ଼ା ପଢ଼ି ଦେଉଛନ୍ତି।\" ଏହାର ପିଲାକୁ ଉତ୍ସାହିତ କରନ୍ତୁ।</div>\n      <div class=\"role example\"><span class=\"em\">💡</span> ଉଦାହରଣ (EXAMPLE)</div>\n      <div class=\"body-text\">\"ମୁଁ ବାପା ଦେଖିଲି!\" \"ମୁଁ ମନ୍ଦିର ଦେଖିଲି!\" ପିଲାମାନେ ଚିତ୍ର ଦେଖି ନିଜ ଅନୁଭୂତି କହିଥିବେ।</div>\n    </div>\n  </div>\n\n  <div class=\"step bodha\">\n    <div class=\"step-header\">\n      <span>୨</span>\n      <span>ବୋଧ (Bodha) — Conceptual Understanding / Comprehension</span>\n      <span class=\"duration\">15 Min</span>\n    </div>\n    <div class=\"step-body\">\n      <div class=\"role teacher\"><span class=\"em\">📘</span> ଶିକ୍ଷକ କାର୍ଯ୍ୟ (TEACHER)</div>\n      <div class=\"body-text\">ପୃଷ୍ଠା ୧ ର ଚିତ୍ର ଦେଖାଇ ପଚାରନ୍ତୁ — \"ଏହି ଚିତ୍ରରେ ପିଲାଟି କ'ଣ କରୁଛନ୍ତି? ପାଖରେ ପଶୁଟିର ପିତା କିଏ?\"</div>\n      <div class=\"role example\"><span class=\"em\">💡</span> ଉଦାହରଣ (EXAMPLE)</div>\n      <div class=\"body-text\">ଚିତ୍ର ଦେଖି ଉତ୍ତର ଦେବେ — \"ଚିତ୍ରରେ ପାଛୋଟି, ଜଣା, ଗର, ପିଢ଼ାଟି ଓ ଗୋଟିଏ ଅଛି। ଅନ୍ୟ ପଶୁକୁ ପିଲାଟି ଛିଡ଼େଇ ଦେଉଛନ୍ତି।\"</div>\n    </div>\n  </div>\n\n  <div class=\"step abhyasa\">\n    <div class=\"step-header\">\n      <span>୩</span>\n      <span>ଅଭ୍ୟାସ (Abhyasa) — Practice</span>\n      <span class=\"duration\">10 Min</span>\n    </div>\n    <div class=\"step-body\">\n      <div class=\"role teacher\"><span class=\"em\">📘</span> ଶିକ୍ଷକ କାର୍ଯ୍ୟ (TEACHER)</div>\n      <div class=\"body-text\">\"ଚିତ୍ରରେ ଥିବା ପ୍ରାଣୀକୁ ପାଖ ପାଇ ଦେଖିଦେଉ ପ୍ରାଣୀକୁ ଦେଖା ପାଇ ଦେଖା ଅଙ୍ଗୁଠାରେ ଦେଖନ୍ତୁ?\" ପଚାରନ୍ତୁ କର।</div>\n      <div class=\"role example\"><span class=\"em\">💡</span> ଉଦାହରଣ (EXAMPLE)</div>\n      <div class=\"body-text\">ପାଉସେ ଦେଉସେ ଓ କହିବେ — \"ଆଣ୍ଟ ପାଣ, ଅଲୁଥ୍, ବିର୍ପିୟା, ଡାଉ ଓ ଏଡ଼ ଦେଖ୍ୟା।\"</div>\n    </div>\n  </div>\n\n  <div class=\"step prayoga\">\n    <div class=\"step-header\">\n      <span>୪</span>\n      <span>ପ୍ରୟୋଗ (Prayoga) — Application</span>\n      <span class=\"duration\">10 Min</span>\n    </div>\n    <div class=\"step-body\">\n      <div class=\"role teacher\"><span class=\"em\">📘</span> ଶିକ୍ଷକ କାର୍ଯ୍ୟ (TEACHER)</div>\n      <div class=\"body-text\">\"ତୁମେ ନିଜ ମଙ୍ଗଳାରୁ ପାଖରୁ ଦେଖୁଥିବା ଏକ ଗାଁକୁ ପାଖ ପାଇ ଦେଖ୍ୟା ପାହୁଣ୍ଡ ଦେଖା ଏଡ଼ ଦେଖ୍ୟା ପାଇଁ କରନ୍ତି?\"</div>\n      <div class=\"role example\"><span class=\"em\">💡</span> ଉଦାହରଣ (EXAMPLE)</div>\n      <div class=\"body-text\">\"ମାଆ, ଫୁଲ, କୋଡ଼ାଉ, ମୁଣ୍ଡଗୋଣ୍ଡ, ମନ୍ଦିରା ପାଇ ଦେଖୁଛି ମନ୍ଦିରା ମନ୍ଦିରାରୁ ମନ୍ଦିରା ଦେଖୁଛି।\"</div>\n    </div>\n  </div>\n\n  <div class=\"step prasara\">\n    <div class=\"step-header\">\n      <span>୫</span>\n      <span>ପ୍ରସାର (Prasara) — Expansion / Extension</span>\n      <span class=\"duration\">5 Min</span>\n    </div>\n    <div class=\"step-body\">\n      <div class=\"role teacher\"><span class=\"em\">📘</span> ଶିକ୍ଷକ କାର୍ଯ୍ୟ (TEACHER)</div>\n      <div class=\"body-text\">ପିଲାମାନଙ୍କୁ ଘର ଫେରାଇ ଚିତ୍ର ଉପରେ ୧ ଟି ଗଠିତ ବାକ୍ୟ ମନେ ମନେ ପ୍ରସ୍ତୁତ କରିବାକୁ କୁହନ୍ତୁ।</div>\n      <div class=\"role example\"><span class=\"em\">💡</span> ଉଦାହରଣ (EXAMPLE)</div>\n      <div class=\"body-text\">ଚିତ୍ର ଆଧାରରେ ନୂଆ ବାକ୍ୟ ପ୍ରସ୍ତୁତ କରି ଘର ଫେରାନ୍ତି ଓ ପରଦିନ ଶ୍ରେଣୀରେ କୁହନ୍ତି।</div>\n    </div>\n  </div>\n\n  <!-- ═════ Visual Direction ═════ -->\n  <div class=\"visual-cue\">\n    <span class=\"label\">🖼️ ଚିତ୍ର / ଦୃଶ୍ୟ ନିର୍ଦ୍ଦେଶ :</span>\n    ପୃଷ୍ଠା ୧ର ଅଗ୍ରଭାଗରେ ମୁଦ୍ରିତ ଦେଉଥିବା ପରିବାରର ବଡ଼ ଚିତ୍ର — ଅଭ୍ୟାସ ସୋପାନରେ ବ୍ୟବହାର କରନ୍ତୁ।\n  </div>\n\n  <!-- ═════ Assessment + Activity ═════ -->\n  <div class=\"grid-2\">\n    <div class=\"info-card\">\n      <div class=\"h\">📝 ମୂଲ୍ୟାୟନ — ମୌଖିକ</div>\n      <ol>\n        <li>ବାପା କେଉଁଠି ଅଛି?</li>\n        <li>ଚିତ୍ରରେ କେଉଁ ରଙ୍ଗ ଅଧିକ ଅଛି?</li>\n      </ol>\n    </div>\n    <div class=\"info-card activity\">\n      <div class=\"h\">🎨 କାର୍ଯ୍ୟକଳାପ</div>\n      <div>ଯୋଡ଼ିରେ ପ୍ରଶ୍ନୋଉର ଖେଳ।</div>\n    </div>\n  </div>\n\n  <!-- ═════ Write + HOTS ═════ -->\n  <div class=\"grid-2\" style=\"margin-top: 10px;\">\n    <div class=\"info-card write\">\n      <div class=\"h\">✍️ ଲିଖନ</div>\n      <ol>\n        <li>ଗୋଟିଏ ପ୍ରଶ୍ନ ଲେଖ।</li>\n        <li>ଅଜା ଶବ୍ଦଟି ଲେଖ।</li>\n      </ol>\n    </div>\n    <div class=\"info-card hots\">\n      <div class=\"h\">🧠 HOTS ପ୍ରଶ୍ନ</div>\n      <div>ଚିତ୍ରର କେଉଁ ଜିନିଷ ବାଦ ଦେଲେ ଚିତ୍ରଟି ବଦଳିଯିବ?</div>\n    </div>\n  </div>\n\n  <!-- ═════ Inclusive Education ═════ -->\n  <div class=\"inclusive\">\n    <div class=\"h\">♿ ସମାବେଶୀ ଶିକ୍ଷା</div>\n    <ul>\n      <li><b>ଧୀରଗତି ଶିକ୍ଷାର୍ଥୀ :</b> ଚିତ୍ରର ଗୋଟିଏ ଅଂଶ ଦେଖାଇ ଗୋଟିଏ ଶବ୍ଦ କହିବାକୁ କୁହନ୍ତୁ।</li>\n      <li><b>ଅଗ୍ରଗାମୀ ଶିକ୍ଷାର୍ଥୀ :</b> ଚିତ୍ର ଆଧାରରେ ପାଞ୍ଚ ବାକ୍ୟର ବର୍ଣ୍ଣନା ଦେବାକୁ କୁହନ୍ତୁ।</li>\n      <li><b>ବିଶେଷ ଆବଶ୍ୟକତା :</b> ବଡ଼ ଆକାରର ଚିତ୍ର କାର୍ଡ ଓ ଆଗ ଧାଡ଼ିରେ ବସିବାର ସୁବିଧା ଦିଅନ୍ତୁ।</li>\n    </ul>\n  </div>\n\n  <!-- ═════ Bottom tri-column ═════ -->\n  <div class=\"tri-col\">\n    <div class=\"cell\">\n      <div class=\"h\">ମୂଲ୍ୟବୋଧ</div>\n      <div>ସହଯୋଗ, ପରସ୍ପରକୁ ଶୁଣିବା।</div>\n    </div>\n    <div class=\"cell century\">\n      <div class=\"h\">୨୧ଶ ଶତାବ୍ଦୀ ଦକ୍ଷତା</div>\n      <div>ଭାବ ବିନିମୟ, ପ୍ରଶ୍ନ ପଚାରିବା।</div>\n    </div>\n    <div class=\"cell nep\">\n      <div class=\"h\">NEP 2020 ସମନ୍ୱୟ</div>\n      <div>ଆଲୋଚନା ଓ ଅନ୍ଧେଷଣାଧିଉକ ଶିକ୍ଷଣ।</div>\n    </div>\n  </div>\n\n  <div class=\"nav-row no-print\">\n    <button class=\"secondary\" onclick=\"window.parent?.postMessage({type:'slp-prev'},'*')\">‹ Previous</button>\n    <div style=\"font-size:9pt;color:#64748b;font-weight:600\">🔒 Premium content — LessonGuru Odisha</div>\n    <button onclick=\"window.parent?.postMessage({type:'slp-next'},'*')\">Next ›</button>\n  </div>\n\n</article>\n</body>\n</html>\n"

